// ?Reset_Device@DX8Wrapper@@SA_N_N@Z
// partial score=0.4 date=2026-09-27
//
// PASTE-READY FRAGMENT, not a standalone TU.  The real body belongs in
//   game/Libraries/Source/WWVegas/WW3D2/dxwrapper.cpp  (58 landed methods)
// which already carries the static-shape skeleton (IsInitted/D3DDevice guard,
// the MAX_VERTEX_STREAMS release loop, the index-buffer release, the
// m_pCleanupHook release, DynamicVB/IB _Deinit, the two shader-constant
// memsets, FrameCount = 0, TestCooperativeLevel + Reset, the reload_assets
// block, Invalidate_Cached_Render_States and Set_Default_Global_Render_States).
// The declarations below go immediately above DX8Wrapper::Reset_Device in
// that file; the body block replaces the body it currently has.
//
// Retail extent is 969 bytes (0x009082B0-0x00908679), not the ledger's 962:
// the final `ret` ends at 0x00908678 and one int3 pads to the 16-aligned
// 0x00908680 that ?Enumerate_Devices@DX8Wrapper@@KAXXZ starts at.
// Land with --replace-existing at 969.
//
// ---------------------------------------------------------------------------
// MEASURED FRAME MODEL  (derived by tracking esp through the retail bytes;
// every offset below is E-relative, E = entry esp)
// ---------------------------------------------------------------------------
//   prologue  mov eax,fs:[0] / push -1 / push <scope handler> / push eax /
//             mov fs:[0],esp / sub esp,0x14 / push ebx / xor ebx,ebx
//   body esp  E-0x28 for the whole body; `push esi` at +0x34 is the only
//             extra save (popped at +0x02db on the failure path and +0x03a4
//             on the success path).  `add esp,0x20; ret` therefore follows
//             two pops, which fixes the body esp at E-0x28 exactly.
//   frame map E-0x28..E-0x25 = saved esi
//             E-0x24..E-0x21 = saved ebx
//             E-0x20..E-0x0d = 0x14 bytes of locals
//             E-0x0c        = SEH previous handler
//             E-0x08        = SEH scope handler
//             E-0x04        = SEH state  (7 stores: 0,1,0,-1,2,0,3,4,3,0,-1)
//   locals    E-0x1c = StringClass, live only in the hr != D3D_OK branch
//             E-0x1d = one-byte bool temporary (the `has_texture` flag)
//             E-0x18 = the counted asset held for the WHOLE body; this is
//                      the `this` of 0x0090E260 (release walk) and 0x0090E2A0
//                      (recreate walk); its dtor is the `Release_Ref` at
//                      +0x039f with the state reset to -1
//             E-0x14 = the registry AssetReference temporary of the FIRST
//                      walk (+0x0120 ctor slot) and, separately, the counted
//                      asset declared inside the reload_assets block whose
//                      dtor is the `Release_Ref` at +0x0380
//             E-0x10 = the registry AssetReference temporary of the SECOND
//                      walk (+0x0314 ctor slot)
//   globals   0x0134050C IsInitted (byte)   0x01340534 D3DDevice
//             0x01340580 FrameCount           0x0134058C m_pCleanupHook
//             0x01340594 number_of_DX8_calls  0x013405A0.. shader constants
//             0x01340600 Vertex_Shader_Constants (0x600 bytes = 0x180 dwords)
//             0x0134110C int[2] = {4,4} written by the vertex-buffer loop
//             0x01341118 / 0x0134111A two shorts zeroed by that loop
//             0x0134111C / 0x0134112C shorts zeroed by the index-buffer release
//             0x01341120 VertexBufferClass *[2]   0x01341128 IndexBufferClass *
//             0x01341150 Pixel_Shader_Constants (0x80 bytes = 0x20 dwords)
//             0x013411E8 consecutive-DX8-error counter, +1 per DX8CALL,
//                      tested against 0x32 (50) and cleared on both exits
//             0x0133F49C render_state_changed, |0x10000 per vertex buffer and
//                      |0x20000 for the index buffer
//             0x012D9124 the registry's "no asset" sentinel char *
//
// ---------------------------------------------------------------------------
// WHAT RETAIL DOES THAT THE CURRENT SOURCE DOES NOT  (all six are missing
// source constructs, not byte-level levers; each needs a shared header or
// shim, which is why this is a blocked/partial and not a shape hunt)
// ---------------------------------------------------------------------------
// 1. NO SEH FRAME AT ALL in the current body.  /EHsc only emits one when a
//    scope holds an object with a non-trivial destructor.  Experiment: adding
//    one 4-byte holder with `~H(){ if (m_p) m_p->Release_Ref(); }` DOES bring
//    a frame in, but the wrong shape --
//        ours  push -1 / push 0 / mov eax,fs:[0] / mov fs:[0],esp / push ecx
//        retail mov eax,fs:[0] / push -1 / push handler / push eax / mov fs:[0],esp
//    i.e. retail saves the previous handler and ours does not, and retail
//    loads fs:[0] before the pushes.  tools/eh_levers.py offers only /EHsc-
//    and _STLP_NO_EXCEPTIONS for this TU and neither restores the long form.
//    The long form plus the mixed byte/dword writes to the same state slot
//    (mov BYTE [E-4],0/1/2/3 and mov DWORD [E-4],-1) is what MSVC emits for a
//    function with more than one cleanup scope, so at least two of the three
//    scopes (E-0x18, E-0x1c, E-0x14/-0x10) have to be present before the
//    prologue is worth chasing.
// 2. THE TWO REGISTRY WALKS ARE INLINED, TWICE, and they are the bulk of the
//    missing bytes (+0x0107..+0x0163 and +0x02fe..+0x0358, 157 bytes).
//    Both have the identical shape, differing only in which method the walk
//    calls and which local receives the assignment:
//        Rva009EBBC0(0x544558);                       // 'TEX' asset stream
//        for (;;) {
//            bool has;
//            {   H a = Rva009EBDC0();                 // ctor into E-0x14
//                held = a;                            // CALL 0x0090DB10
//                has = (held != 0);                   // setne off [eax]
//            }                                        // if (a.m_p) a.m_p->Release_Ref()
//            if (has) held->bfmeGo973A();             // 0x0090E260 / 0x0090E2A0
//            if (!has) break;
//        }
//    The inner `{ }` is required: it is what puts state 1/0 around the
//    temporary's release and places the release BETWEEN the setne and the
//    method call, exactly as retail does.  0x0090DB10 is
//    ??4Gen_0090DB10@@QAEAAV0@ABV0@@Z, already matched in
//    game/GameEngine/Source/Common/S3TaggedAssignments.cpp; the holder is the
//    same one-pointer class (`class Gen_0090DB10 { Gen_0090DB10 &operator=(...);
//    BfmeTagged *m_bfmePtr; }`), so declaring that class name here and letting
//    the linker bind the already-matched operator= is the cheapest route.
// 3. BFME'S DX8CALL_HRES INCREMENTS TWO COUNTERS.  The vendored game header
//    (game/.../dx8wrapper.h:138, NDEBUG arm) does
//    `res = ...->x; number_of_DX8_calls++;`.  Retail does
//        mov edx,[0x01340594] / inc edx / mov [0x01340594],edx
//        mov ecx,[0x013411E8] / inc ecx / mov [0x013411E8],ecx
//    so BFME carries a second consecutive-error counter the ZH header has not
//    got.  That is a shared-header edit (full gate) affecting every DX8Wrapper
//    caller.
// 4. THE SHARED D3D8 SHIM PUTS Reset ON THE WRONG VTABLE SLOT.
//    inputs/reference/shims/d3d8_shim_validated.h:281-297 omits
//    GetSwapChain and GetNumberOfSwapChains, so `Reset` lands at vtable +0x38.
//    Retail calls slot +0x40 (the standard IDirect3DDevice8 order) with
//    &_PresentParameters (0x013400C4) at +0x01b4/+0x01ba.  Any body that calls
//    Reset cannot match until those two slots exist.  No currently matched row
//    calls Reset, so the repair is provably confined, but it is a
//    vendored-shim edit and needs the full gate.
// 5. THE hr != D3D_OK REPORTER (+0x01e1..+0x02b6, 214 bytes) is absent:
//        StringClass s(g_emptyStringSentinel);          // StringClass::Get_String(0x16,false)
//        s.Uninitialised_Grow(0x16);
//        s = s + DXGetErrorString9A(hr);                // _DXGetErrorString9A@4 @ 0x00AD548E
//        s = s + "\nFrame:%d, %s(%d):\n";               // literal at 0x01080294
//        if (g_dx8ErrorCount >= 0x32) {                 // tested BEFORE the +1 is undone
//            _bfme_debugRecordCallsite(1);
//            TheBfmeAwakenDebug->slot60();
//            TheBfmeAwakenDebug->slot6C(0,0)->slot38(
//                "Direct3D device reset failed after multiple attempts")   // 0x0113A46C
//                                                       ->slot4C(1);
//        }
//        return false;
//    The 0x16-byte seed is the literal at 0x0113A4A4, "Device reset failed: "
//    (22 bytes including the NUL) -- the length store `mov [eax-4],0x15` and
//    the 0x16 grow both follow from that count, and verify_string_refs will
//    reject any other spelling.  The long report string at 0x0113A46C is
//    0x113A46C..0x113A49B, 52 bytes.
// 6. The mesh-renderer pair either side of the memsets:
//        TheDX8MeshRenderer->m();    // 0x00944C30 before, before Rva0090F050
//        Rva0090F050();              // matched: game/GameEngineDevice/Source/
//                                    //   W3DDevice/Common/System/
//                                    //   DeviceReset_releaseResources_rva0090f050.cpp
//        TheDX8MeshRenderer->m();    // 0x00944C40 after the reload_assets block
//    0x00944C30/0x00944C40 have no declaration anywhere in game/ yet.
//
// Loop shape in the ALREADY-MATCHING part: retail uses `add esi,4` where the
// current source materialises the 4 in edi and emits `add esi,edi` plus
// `mov [esi+...],edi` in place of the immediate.  That is pure register
// pressure and should fall out once the missing blocks are present.
//
// Naming: keep ?Reset_Device@DX8Wrapper@@SA_N_N@Z.  It is proven twice over --
// the matched caller ?Set_Device_Resolution@DX8Wrapper@@KA_NHHHH_N@Z in this
// same file and ?Begin_Render@WW3D@@ in WW3D_Begin_Render_Bfme.cpp both call
// it, and the parameter is the `bool` the five matched DX8Wrapper siblings
// take.  The 969-byte extent is the proven correction (see the header).

// ---------------------------------------------------------------------------
// TU-LOCAL DECLARATIONS (paste above DX8Wrapper::Reset_Device)
// ---------------------------------------------------------------------------

// The counted asset the two registry walks hand the reference to.  Four
// bytes: a single pointer, default-constructed by a bare store of zero (no
// constructor call at +0x0114), assigned through the matched tag-checked
// operator= at 0x0090DB10, and destroyed by an inline `if (p) p->Release_Ref()`
// (0x009EB7A0).  The two walk methods are already matched, address-derived
// names, in game/GameEngine/Source/Common/BfmeConv973.cpp (0x0090E260) and
// game/GameEngine/Source/Common/BfmeConv1756.cpp (0x0090E2A0); they take the
// holder itself as `this`, which is why the call at +0x015E and +0x0353 loads
// the holder's stack slot rather than the pointer it holds.
class BfmeTagged
{
public:
	virtual void bfmeSlot0(void);
	virtual void bfmeSlot1(void);
	virtual void bfmeSlot2(void);
	virtual void bfmeSlot3(void);
	virtual void bfmeSlot4(void);
	virtual void bfmeSlot5(void);
	virtual void bfmeSlot6(void);
	virtual void bfmeSlot7(void);
	virtual void bfmeSlot8(void);
	virtual void bfmeSlot9(void);
	virtual void bfmeSlot10(void);
	virtual void bfmeSlot11(void);
	virtual void bfmeSlot12(void);
	virtual unsigned int bfmeTag(void);			// slot 13, vtable+0x34
	void bfmeRelease(void);							// retail 0x009EB7A0
	unsigned short m_bfmeRefCount;					// +0x04
};

// Declared, not defined: the definition lives in
// game/GameEngine/Source/Common/S3TaggedAssignments.cpp as
// ??4Gen_0090DB10@@QAEAAV0@ABV0@@Z.  Naming the class Gen_0090DB10 here is
// what makes the linker bind that object; any other spelling compiles to a
// call the resolver cannot place.
class Gen_0090DB10
{
public:
	Gen_0090DB10 &operator=(const Gen_0090DB10 &other);

private:
	BfmeTagged *m_bfmePtr;
};

// The registry's counted-asset handle, returned BY VALUE through a hidden
// pointer (retail: lea ecx,[E-0x14] / push ecx / call 0x009EBDC0).  Four
// bytes; its destructor is the inline release at +0x014F / +0x0344.
class AssetReference
{
public:
	AssetReference &operator=(const AssetReference &other);	// pin 0x0090DB10
private:
	BfmeTagged *m_bfmePtr;
};

// Declared, not defined: both are already matched elsewhere.
void Rva009EBBC0(int asset_type);					// 0x009EBBC0, cdecl
AssetReference Rva009EBDC0();							// 0x009EBDC0
void Rva0090F050(void);								// 0x0090F050
void _bfme_debugRecordCallsite(int kind);				// 0x008896A0, cdecl
extern char *Rva012D9124EmptyAsset;					// 0x012D9124
extern int Rva013411E8Dx8ErrorCount;					// 0x013411E8
extern int TheBfmeAwakenDebug_dx8Errors;				// 0x01336E5C
extern DX8MeshRendererClass *TheDX8MeshRenderer;		// 0x0134B0E8
extern const char _Rva0113A46C_MultipleAttempts[];	// "Direct3D device reset
													//  failed after multiple attempts"

// ---------------------------------------------------------------------------
// BODY (replaces the body currently at game/.../dxwrapper.cpp:710)
// ---------------------------------------------------------------------------
