{
	if ((IsInitted) && (D3DDevice != NULL)) {

		// +0x0034 .. +0x0102  unchanged from the current source
		WW3D::_Invalidate_Textures();					// NOT a call in retail:
														// the walk below is it
		for (unsigned i=0;i<MAX_VERTEX_STREAMS;++i) Set_Vertex_Buffer (NULL,i);
		Set_Index_Buffer (NULL, 0);
		if (m_pCleanupHook) m_pCleanupHook->ReleaseResources();
		DynamicVBAccessClass::_Deinit();
		DynamicIBAccessClass::_Deinit();

		// +0x0107 .. +0x0163  the release walk (inline)
		Gen_0090DB10 held;								// E-0x18, store of zero only
		Rva009EBBC0(0x544558);
		for (;;) {
			bool has;
			{
				AssetReference a = Rva009EBDC0();
				held = a;
				has = (held != 0);
			}
			if (has) held.bfmeGo973A();
			if (!has) break;
		}

		// +0x0165 .. +0x018e
		TheDX8MeshRenderer->m();
